{
  "name": "scenario_start",
  "description": "Start the unchanged Node service in a private Docker network-none container, arrange exact HTTP fixtures/config/files, wait for readiness and return a leased session. No host ports, sockets, environment credentials or live HTTP fallback. Poll with job if still running. Use scenario_stop when finished.",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "workspace": {
        "type": "string",
        "description": "Writable workspace id"
      },
      "package": {
        "type": "string",
        "description": "Repository-relative path to scenario.json"
      },
      "view": {
        "type": "boolean",
        "description": "Include an interactive result view; default true",
        "default": true
      },
      "job": {
        "type": "string",
        "description": "Poll a scenario_start job; workspace/package may be omitted"
      },
      "ttl_ms": {
        "type": "integer",
        "default": 300000,
        "minimum": 1000,
        "maximum": 3600000
      }
    },
    "required": []
  }
}
